<?php
declare(strict_types=1);requireRole('store-keeper');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='approved-dispatches';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT);if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$id)$errors[]='Invalid dispatch request.';if(!$errors){try{$db=database();$db->beginTransaction();$s=$db->prepare("SELECT * FROM goods_requests WHERE id=:id AND status='approved-awaiting-dispatch' FOR UPDATE");$s->execute(['id'=>$id]);$request=$s->fetch();if(!$request)throw new RuntimeException('This request is no longer available for dispatch.');$stock=$db->prepare('SELECT quantity FROM inventory_items WHERE id=:item FOR UPDATE');$stock->execute(['item'=>$request['item_id']]);$available=(int)$stock->fetchColumn();if($available<(int)$request['quantity'])throw new RuntimeException("Insufficient central stock. Available: $available.");$deduct=$db->prepare('UPDATE inventory_items SET quantity=quantity-:quantity WHERE id=:item');$deduct->execute(['quantity'=>$request['quantity'],'item'=>$request['item_id']]);$pool=$db->prepare('INSERT INTO division_inventory(ds_division_id,item_id,quantity) VALUES(:division,:item,:quantity) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)');$pool->execute(['division'=>$request['destination_ds_division_id'],'item'=>$request['item_id'],'quantity'=>$request['quantity']]);$update=$db->prepare("UPDATE goods_requests SET status='dispatched',dispatched_by=:user,dispatched_at=NOW() WHERE id=:id");$update->execute(['user'=>$_SESSION['user_id'],'id'=>$id]);$db->commit();logActivity('Dispatch','Dispatched approved goods request','GR-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),'dispatched');$_SESSION['flash_success']='Goods released to the destination division.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=approved-dispatches');exit;}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to dispatch goods.';}}}
try{$rows=database()->query("SELECT g.*,i.item_name,i.variety,i.quantity central_stock,ds.name division_name,d.name district_name,requester.full_name requester_name,approver.full_name approver_name FROM goods_requests g JOIN inventory_items i ON i.id=g.item_id JOIN ds_divisions ds ON ds.id=g.destination_ds_division_id JOIN districts d ON d.id=ds.district_id JOIN users requester ON requester.id=g.requested_by JOIN users approver ON approver.id=g.approved_by WHERE g.status='approved-awaiting-dispatch' ORDER BY g.approved_at,g.id")->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$rows=[];$errors[]='Approved dispatches are unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Approved Requests Ready for Dispatch | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body class="store-page store-dispatch-page"><?php require __DIR__.'/../../includes/store-keeper-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Approved Requests Ready for Dispatch</h1></div></header><main class="dashboard-content dispatch-page"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="dispatch-card"><div class="dispatch-card-header"><h2>Approved Requests Ready for Dispatch</h2></div><div class="dispatch-table-wrap"><table class="dispatch-table"><thead><tr><th>Request ID</th><th>Item</th><th>Qty</th><th>Central Stock</th><th>Requested By</th><th>Destination</th><th>Approved By</th><th>Approved On</th><th>Action</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9" class="empty-table">No approved requests are waiting for dispatch.</td></tr><?php else:foreach($rows as $r):?><tr><td>GR-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''),ENT_QUOTES,'UTF-8')?></td><td><?=(int)$r['quantity']?></td><td><?=(int)$r['central_stock']?></td><td><?=htmlspecialchars($r['requester_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['district_name'].' / '.$r['division_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['approver_name'],ENT_QUOTES,'UTF-8')?></td><td><?=date('d M Y H:i',strtotime($r['approved_at']))?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><button class="admin-primary-action">Release Items</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
